            if (m.stage_live[sl]) cudaStreamWaitEvent(m.copy, m.used[sl], 0);
            cudaMemcpyAsync(m.stage_dev[sl], b, (size_t) lay.blob_bytes(l), cudaMemcpyHostToDevice, m.copy);
