}
if (half == 1 && strata::kernels::cvec().covers(l))   // --control-vector-scaled

raw_tool_result.content:
            strata::kernels::qsa_decode_attn_batch(m.q + t0 * ZV, pools, m.sel_ids + t0 * m.cap,
